window.docContents[84].resolve({"/Security/Threat-Model/#threat-model":{"contents":"YAML parsers face several categories of attack:\n\n* Billion-laugh attacks — deeply nested aliases that expand\nexponentially, exhausting memory* Denial of service — extremely long strings, deeply nested\nstructures, or very large collections that consume excessive resources* Arbitrary code execution — YAML tags that trigger object\ndeserialization in languages with unsafe constructors\n(e.g., Python's !!python/object)* Duplicate key confusion — multiple identical keys in a mapping,\nwhere different consumers may pick different values\n\nL4YAML mitigates all of these through its ParserLimits configuration.\n\n","context":"L4YAML: A Verified YAML 1.2.2 Parser in Lean 4\u0009Security","header":"4.1. Threat Model","id":"/Security/Threat-Model/#threat-model"}});